with recent_inventory as (select *, datediff(current_date(), last_restock) as days_since_last_restock from inventory where product_id in (2, 5, 6) and last_restock < '2023-08-01'), ProductIdSummary as (select product_id, store_id, count(distinct days_since_last_restock) as unique_products, min(days_since_last_restock) as min_days_since_last_restock from recent_inventory group by product_id, store_id) select product_id, store_id, unique_products, min_days_since_last_restock from ProductIdSummary order by store_id asc, product_id asc limit 10;
